'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var Complex64 = require( '@stdlib/complex/float32/ctor' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var realf = require( '@stdlib/complex/float32/real' );
var imagf = require( '@stdlib/complex/float32/imag' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );
var isComplexLike = require( '@stdlib/assert/is-complex-like' );
var pow = require( '@stdlib/math/base/special/pow' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var factory = require( './../lib' );


// FUNCTIONS //

/**
* Predicate function for complex128.
*
* @private
* @param {Complex128} value - array element
* @param {NonNegativeInteger} idx - array element index
* @param {Object} arr - array instance
* @returns {boolean} boolean indicating whether a value passes a test
*/
function predicate128( value ) {
	return ( real( value ) === -imag( value ) );
}

/**
* Predicate function for complex64.
*
* @private
* @param {Complex64} value - array element
* @param {NonNegativeInteger} idx - array element index
* @param {Object} arr - array instance
* @returns {boolean} boolean indicating whether a value passes a test
*/
function predicate64( value ) {
	return ( realf( value ) === -imagf( value ) );
}

/**
* Creates a benchmark function for complex128.
*
* @private
* @param {PositiveInteger} len - array length
* @returns {Function} benchmark function
*/
function createBenchmark128( len ) {
	var Complex128Array;
	var arr;
	var i;

	Complex128Array = factory( 'complex128' );
	arr = [];
	for ( i = 0; i < len-1; i++ ) {
		arr.push( new Complex128( i, i ) );
	}
	arr.push( new Complex128( len-1, -( len-1 ) ) );
	arr = new Complex128Array( arr );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = arr.find( predicate128 );
			if ( typeof z !== 'object' ) {
				b.fail( 'should return an object' );
			}
		}
		b.toc();
		if ( !isComplexLike( z ) ) {
			b.fail( 'should return a complex number' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}

/**
* Creates a benchmark function for complex64.
*
* @private
* @param {PositiveInteger} len - array length
* @returns {Function} benchmark function
*/
function createBenchmark64( len ) {
	var Complex64Array;
	var arr;
	var i;

	Complex64Array = factory( 'complex64' );
	arr = [];
	for ( i = 0; i < len-1; i++ ) {
		arr.push( new Complex64( i, i ) );
	}
	arr.push( new Complex64( len-1, -( len-1 ) ) );
	arr = new Complex64Array( arr );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = arr.find( predicate64 );
			if ( typeof z !== 'object' ) {
				b.fail( 'should return an object' );
			}
		}
		b.toc();
		if ( !isComplexLike( z ) ) {
			b.fail( 'should return a complex number' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var len;
	var min;
	var max;
	var f;
	var i;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( i = min; i <= max; i++ ) {
		len = pow( 10, i );
		f = createBenchmark128( len );
		bench( format( '%s::complex128:find:len=%d', pkg, len ), f );
	}
	for ( i = min; i <= max; i++ ) {
		len = pow( 10, i );
		f = createBenchmark64( len );
		bench( format( '%s::complex64:find:len=%d', pkg, len ), f );
	}
}

main();
